<template>
    <div id="App" v-if="openned">
        <div id="LeaderBoardBox">
            <div id="LeaderBoardBannerBox">
                <!-- <img src="img/LegendaryBanner.png" alt="" class="LeaderBoardImageBanner"> -->
            </div>

            <div id="LeaderBoardTitleBox">
                <h2 class="LeaderBoardTitle">{{translate.TR_TITLE}}</h2>
                <p class="close" @click="close">X</p>
            </div>

            <div id="LeaderBoardBodyBox">
                <div id="LeaderBoardRankBox">
                    <table>
                        <tr>
                            <th>#</th>
                            <th></th>
                            <th>{{translate.TR_PLAYER}}</th>
                            <th>{{translate.TR_KILLS}}</th>
                            <th>{{translate.TR_DEATHS}}</th>
							<th>K/D</th>
                            <th>{{translate.TR_SCORE}}</th>
                        </tr>

                        <tr
                            v-for="(item,index) in sort(players)"
                            :key="index"
                        >
                            <td>{{index+1}}</td>
                            <td><img :src="findRank(item.score).img" alt=""></td>
                            <td>{{item.name}}</td>
                            <td>{{item.kills}}</td>
                            <td>{{item.deaths}}</td>
							<td>{{item.deaths == 0 ? item.kills : (item.kills/item.deaths).toFixed(2)}}</td>
                            <td>{{item.score}}</td>
                        </tr>
                    </table>
                </div>

                <div id="LeaderBoardPlayerRankBox">
                    <div id="LeaderBoardPlayerTitleBox">
                        <p>{{translate.TR_YOUR_RANK}}</p>
                    </div>

                    <div id="LeaderBoardPlayerInfosBox">
                        <div id="LeaderBoardPlayerPedBox">
                            <div class="LeaderBoardPlayerListStatusItemImage">
                                <img :src="findRank(player.score).img" alt="">
                            </div>

                            <div class="LeaderBoardPlayerCurrentRank">
                                <p>{{findRank(player.score).name}}</p>
                            </div>

                            <div class="LeaderBoardPlayerCurrentScoreRank">
                                <p>{{player.score}}/{{findRank(player.score).max_score}}</p>

                                <div class="circular">
                                    <div class="inner"></div>
                                    <div class="number">{{Math.round((findRank(player.score).score-player.score)*100/(findRank(player.score).score-findRank(player.score).max_score))}}%</div>
                                    <div class="circle">
                                    <div class="bar left">
                                        <div class="progress" :style="BarLeft"></div>
                                    </div>
                                    <div class="bar right">
                                        <div class="progress" :style="BarRight"></div>
                                    </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div id="LeaderBoardPlayerListStatusBox">
                            <div class="LeaderBoardPlayerListStatusItem">
                                <p>{{translate.TR_PLAYER}}:</p>
                                <p>{{player.name}}</p>
                            </div>

                            <div class="LeaderBoardPlayerListStatusItem">
                                <p>{{translate.TR_KILLS}}:</p>
                                <p>{{player.kills}}</p>
                            </div>

                            <div class="LeaderBoardPlayerListStatusItem">
                                <p>{{translate.TR_DEATHS}}:</p>
                                <p>{{player.deaths}}</p>
                            </div>
							
							<div class="LeaderBoardPlayerListStatusItem">
                                <p>{{translate.TR_SCORE}}:</p>
                                <p>{{player.score}}</p>
                            </div>

                            <div class="LeaderBoardPlayerListStatusItem">
                                <p>K/D:</p>
                                <p>{{player.deaths == 0 ? player.kills : (player.kills/player.deaths).toFixed(2)}}</p>
                            </div>

                            <div class="LeaderBoardPlayerListStatusItem">
                                <p>{{translate.TR_POSITION}}:</p>
                                <p>{{player.position}}</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>

import axios from 'axios';

export default {
    components: {
        
    },

    data: function(){
        return({
            // page : "Home",

            players: [
                {
                    name: "zFightxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
                    kills: "10000000",
                    deaths: "300000",
                    score: 600000
                },
                {
                    name: "zFightx2",
                    kills: "10000",
                    deaths: "5000",
                    score: 600
                },
                {
                    name: "zFightx3",
                    kills: "10000",
                    deaths: "3000",
                    score: 700
                }
            ],
            player: {
                name: "zFightxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
                kills: "10000",
                deaths: "5000",
                score: 800,
                position: 1,
            },
            ranks:[
                {
                    name: "Silver 1",
                    img: "img/1.png",
                    score: 0,
                    max_score: 600,
                },

                {
                    name: "Silver 2",
                    img: "img/2.png",
                    score: 600,
                    max_score: 800,
                }
            ],

            BarLeft: {
                transform: "rotate(180deg)",
            },
            BarRight: {
                transform: "rotate(180deg)",
            },

            translate:{
                TR_TITLE: "Title of the Leaderboard here",

                TR_PLAYER : "PLAYER",
                TR_KILLS: "KILLS",
                TR_DEATHS: "DEATHS",
                TR_SCORE: "SCORE",

                TR_YOUR_RANK: "Your Rank",
                TR_POSITION: "POSITION",
            },

            NameResource: "lg_leaderboard",
            openned: false,
        })
    },

    methods: {
        findRank: function(score){
            let rank = {};
            this.sort(this.ranks, true).forEach(element => {
                if(score >= element.score)
                    rank = element;
            });

            return rank;
        },

        calculateDegree: function(){
            const rank = this.findRank(this.player.score); 
            const percentage = Math.round( (rank.score - this.player.score) * 100 / (rank.score - rank.max_score) );
        
            if(percentage <= 50){
                this.BarRight.transform = "rotate(0deg)";
                this.BarLeft.transform = `rotate(${Math.round(180*percentage/50)}deg)`;
            }
            else{
                this.BarLeft.transform = "rotate(180deg)";
                this.BarRight.transform = `rotate(${Math.round(180*(percentage-50)/50)}deg)`;
            }
        },

        sort: function(players, inverse){
            for(let i = 0; i < players.length; i++){
                for(let j = 0; j < players.length; j++){
                    if(inverse){
                        if(Number(players[i].score) < Number(players[j].score)){
                            const aux = players[i];
                            players[i] = players[j];
                            players[j] = aux;
                        }
                    }
                    else{
                        if(Number(players[i].score) > Number(players[j].score)){
                            const aux = players[i];
                            players[i] = players[j];
                            players[j] = aux;
                        }
                        else if(Number(players[i].score) == Number(players[j].score)){
                            if(Number(players[i].kills) > Number(players[j].kills)){
                                const aux = players[i];
                                players[i] = players[j];
                                players[j] = aux;
                            }
                            else if(Number(players[i].kills) == Number(players[j].kills)){
                                if(Number(players[i].deaths) < Number(players[j].deaths)){
                                    const aux = players[i];
                                    players[i] = players[j];
                                    players[j] = aux;
                                }
                            }
                        }
                    }
                }
            }

            return players;
        },

        receiveLua: function(event){
            if(!event || !event.data)
                return;
            
            const lua = event.data;

            if(lua.config){
                this.translate = lua.translate;
                this.NameResource = lua.NameResource;
                this.ranks = lua.ranks;                
            }
            else if(lua.open){
                this.openned = true;

                this.players = lua.players;
                this.player = lua.player;

                this.calculateDegree();
            }
        },

        close: function(){     
            const NameResource = this.NameResource[0];

            axios.post(`https://${NameResource}/close`, {
                
            }).catch(msg => console.log(msg));

            this.openned = false;
        },

        keyPress: function(event){
            const key = event.key;
            
            if(key == "Escape"){
                this.close();
            }
        },
    },

    created: function(){
        window.addEventListener('message', this.receiveLua);  
        window.addEventListener('keydown', this.keyPress);
    },
    destroyed: function(){
        window.removeEventListener('message', this.receiveLua);
        window.removeEventListener('keydown', this.keyPress);
    }

}
</script>

<style>
    /* #07051A */
    /* #FCE400 */
    /* #0A0727 */

    *{
        margin: 0;
        padding: 0;
        box-sizing: border-box;
        list-style: none;
        font-family: 'Roboto', sans-serif;
    }

    *:not(input or select){
        user-select: none;
        -moz-user-select: none;
        -webkit-user-select: none;
    }

    body{
        /* background-image: url("C:\\Users\\zFightx\\Pictures\\ScoreBoard\\BG\\simulacao-ifooddelivery.jpg"); */
        /* background-size: 100%; */
    }

    #App{
        background: rgba(15, 15, 15, 0.466);
        width: 100vw;
        height: 100vh;
        position: absolute;
        top: 0%;
        left: 0;
    }

    #LeaderBoardBox{
        width: 130vh;

        margin: auto;
    }

    #LeaderBoardBannerBox{
        width: 15vh;
        height: 15vh;
        border-radius: 50%;
        overflow: hidden;

        /* margin: auto; */
        /* margin-top: 5vh; */
    }

    #LeaderBoardBannerBox img{
        width: 100%;
    }

    #LeaderBoardTitleBox{
        width: 100%;

        background: rgba(0, 0, 0, 0.849);
        color: white;
        font-size: 1.8vh;
        padding: 2vh 2vh;

        border-radius: 5px;

        margin-top: 5vh;

        display: flex;
        flex-direction: row;
        justify-content: space-between;
        align-items: center;

        /* text-align: center; */
    }

    #LeaderBoardBodyBox{
        display: flex;
        flex-direction: row;

        width: 100%;
    }

    #LeaderBoardRankBox{
        width: 50%;

        max-height: 48vh;
        overflow: hidden;
        overflow-y: scroll;

        margin-top: 5vh;
    }

    #LeaderBoardRankBox::-webkit-scrollbar-track {
        background-color: #6e6e6e;
    }

    #LeaderBoardRankBox::-webkit-scrollbar {
        width: 0.0vh;
        background: rgba(5, 5, 5, 0.8);
    }
    #LeaderBoardRankBox::-webkit-scrollbar-thumb {
        background: rgba(36, 36, 36, 0.8);
        border-radius: 20px;
    }

    table{
        border-collapse: separate;

        border-spacing: 0 0.5vh;
    }

    table *{
        text-align: center;
        font-size: 1.5vh;
        color: rgb(161, 161, 161);

        border: none;
    }

    table th{
        color: white;
    }

    table td:nth-child(3), table td:nth-child(4){
        color: white;
    }

    table td:nth-child(3), table th:nth-child(3){
        text-align: left;
    }

    table td:not(:nth-child(2)){
        padding: 1.5vh 1vh;
    }

    table th{
        padding: 1vh;
    }

    table td:nth-child(3), table th:nth-child(3){
        width: 60%;
    }

    table td:nth-child(3){
        background: rgba(74, 74, 74, 0.39);
        overflow: hidden;
        max-width: 20vh;
        text-overflow: ellipsis;
    }

    table th{
        font-weight: bolder;
    }

    table td:nth-child(2){
        background: rgb(38,38,38);
        background: linear-gradient(180deg, rgba(38,38,38,1) 0%, rgba(38,38,38,1) 27%, rgba(0,0,0,1) 100%);

        max-width: 7vh;
        min-width: 7vh;
    }

    table td img{
        width: 100%;
    }

    table tr:not(:first-child){
        background: rgba(0, 0, 0, 0.55);
        height: 5vh;
    }

    #LeaderBoardPlayerRankBox{
        width: 45%;

        margin-top: 5vh;
        margin-left: 5%;
    }

    #LeaderBoardPlayerTitleBox{
        background: rgba(0, 0, 0, 0.849);
        color: white;
        font-size: 2vh;
        text-align: center;
        padding: 1vh;

        border-radius: 5px;

        margin-bottom: 1vh;
    }

    #LeaderBoardPlayerInfosBox{
        display: flex;
        flex-direction: row;
    }

    #LeaderBoardPlayerPedBox{
        width: 50%;
        height: 42.1vh;
        background: rgba(24, 24, 24, 0.699);
    }

    .LeaderBoardPlayerListStatusItemImage{
        background: rgba(0, 0, 0, 0.55);
        width: 100%;
    }

    #LeaderBoardPlayerListStatusBox{
        width: 50%;
        position: relative;
    }

    .LeaderBoardPlayerListStatusItem{
        display: flex;
        flex-direction: row;
        justify-content: space-between;

        background: rgba(0, 0, 0, 0.55);
        color: white;

        margin-bottom: 1vh;
        padding: 1vh;

        /* max-width: 30vh; */
        overflow: hidden;
    }

    .LeaderBoardPlayerListStatusItem:last-child{
        background: rgba(0, 0, 0, 0.849);
        
        position: absolute;
        width: 100%;
        bottom: 0;
        margin: 0;
    }

    .LeaderBoardPlayerListStatusItemImage img{
        width: 100%;

        background: rgb(38,38,38);
        background: linear-gradient(180deg, rgba(38,38,38,1) 0%, rgba(38,38,38,1) 27%, rgba(0,0,0,1) 100%);
    }

    .LeaderBoardPlayerListStatusItemImage{
        background: none;
        padding: 0;
    }

    .LeaderBoardPlayerCurrentRank{
        text-align: center;
        color: white;
        font-size: 3vh;
        margin-top: 1vh;

        font-weight: 200;
        text-shadow: 1px 10px 10px rgb(206, 182, 147);
    }

    .LeaderBoardPlayerCurrentScoreRank{
        text-align: center;
        color: rgb(150, 150, 150);
        margin-top: 1vh;
    }

    .circular{
        height: 10vh;
        width: 10vh;
        position: relative;  
        /* border:solid green 1px; */

        margin: auto;
        margin-top: 2vh;
    }

    .circular .inner{
        position: absolute;
        z-index: 6;
        top: 50%;
        left: 50%;
        height: 8vh;
        width: 8vh;
        /* margin: -40px 0 0 -40px; */
        transform: translate(-50%, -50%);
        background: rgb(38,38,38);
        background: linear-gradient(180deg, rgba(38,38,38,1) 0%, rgba(38,38,38,1) 27%, rgba(0,0,0,1) 100%);
        border-radius: 100%;
    }

    .circular .number{
        position: absolute;
        top:50%;
        left:50%;
        transform: translate(-50%, -50%);
        z-index:10;
        font-size: 2vh;
        font-weight:500;
        color:#f8f8f8;
    }

    .circular .bar{
        position: absolute;
        height: 100%;
        width: 100%;
        /* background: #fff; */
        -webkit-border-radius: 100%;
        clip: rect(0vh, 10vh, 10vh, 5vh);
    }

    .circle .bar .progress{
        position: absolute;
        height: 100%;
        width: 100%;
        -webkit-border-radius: 100%;
        clip: rect(0vh, 5vh, 10vh, 0vh);
        background: #f1c602;
    }

    .circle .left .progress{
        z-index:1;
        /* animation: left 4s linear both; */
        /* transform: rotate(180deg); */
    }
    @keyframes left{
        100%{
            transform: rotate(180deg);
        }
    }
    .circle .right {
        transform: rotate(180deg);
        z-index:3;
    
    }
    .circle .right .progress{
        /* animation: right 4s linear both; */
        animation-delay:4s;

        /* transform: rotate(180deg); */
    }
    @keyframes right{
        100%{
            transform: rotate(180deg);
        }
    }

</style>